"""Create two self-contained, readable notebooks with nbformat's JSON schema."""
from pathlib import Path
import nbformat as nbf

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "notebooks"

def code(text): return nbf.v4.new_code_cell(text.strip())
def md(text): return nbf.v4.new_markdown_cell(text.strip())

def build_student():
    cells = [
        md("# Student Performance Data Explorer\n\n## Objective\nExplore the genuine UCI Student Performance mathematics data, assess data quality, describe final grades, and communicate patterns with plots. Correlation is descriptive and does not establish causation.\n\n**Source:** [UCI Student Performance (dataset 320)](https://archive.ics.uci.edu/dataset/320/student). The original `student-mat.csv` is semicolon-separated; raw source file is preserved in `data/student_data.csv`."),
        md("## Load and inspect\nPaths are resolved from the repository root, so no personal absolute path is needed. The shared analysis function saves reproducible outputs and the cleaned CSV."),
        code("from pathlib import Path\nimport sys\nfrom IPython.display import display, Image\nROOT = next((p for p in [Path.cwd(), *Path.cwd().parents] if (p / 'src').is_dir()), None)\nif ROOT is None: raise FileNotFoundError('Run this notebook from within the project directory.')\nsys.path.insert(0, str(ROOT / 'src'))\nimport pandas as pd\nfrom data_utils import read_student_data\nfrom student_analysis import run_student_analysis\nraw = read_student_data()\nprint('Shape:', raw.shape)\nprint('Columns:', raw.columns.tolist())\nprint('Data types:'); display(raw.dtypes.to_frame('dtype'))\ndisplay(raw.head(10))\ndisplay(raw.describe(include='all').T)"),
        md("## Data quality and cleaning\nCount missing values and exact duplicates before cleaning. Exact duplicate rows are removed. Missing numeric fields use the column median and categorical fields use the mode; the report records actual before/after counts."),
        code("print('Missing values by column:'); display(raw.isna().sum().to_frame('missing'))\nprint('Duplicate rows:', int(raw.duplicated().sum()))\nresults = run_student_analysis()\ncleaned = pd.read_csv(ROOT / 'data' / 'student_data_cleaned.csv')\nprint('Cleaning summary:', results['cleaning'])\nprint('Cleaned shape:', cleaned.shape)\ndisplay(cleaned.head())"),
        md("## Descriptive statistics\nThe outcome is the final grade (`G3`, displayed as **Math Score**) on the dataset's 0-20 scale. The prior period grades are retained as separate predictors for descriptive comparison."),
        code("score = cleaned['Math Score']\nprint({ 'mean': score.mean(), 'median': score.median(), 'mode': score.mode().tolist(), 'minimum': score.min(), 'maximum': score.max(), 'standard_deviation': score.std() })\ndisplay(cleaned.select_dtypes(include='number').describe().T)\nprint('Pearson correlation matrix for numerical fields:')\ndisplay(cleaned.select_dtypes(include='number').corr().round(2))"),
        md("## Visual analysis\nThe plots are regenerated by the shared script and are also saved as PNGs under `images/` for the report and submission."),
        code("for filename in ['math_score_histogram.png','math_score_boxplot.png','math_scatter_plot.png','correlation_heatmap.png','average_score_by_school.png']:\n    print(filename)\n    display(Image(filename=str(ROOT / 'images' / filename)))"),
        md("## Evidence-based observations and limitations\nThe source contains **395 rows, no missing cells, and no exact duplicate rows**. Final grades average **10.42/20** (median **11**, mode **10**), with Q1 **8** and Q3 **14**; the IQR rule flags **0** observations. The Period 1/final and Period 2/final correlations are **0.801** and **0.905**. Mean final grades are **10.49** at GP and **9.85** at MS. These are descriptive relationships in an observational sample from two Portuguese schools; correlation does not establish causation, and group means do not control for confounders."),
        md("## Conclusion\nThis notebook produces a separately cleaned dataset, quality counts, descriptive statistics, and five labeled figures. See `reports/eda_report.md` for the combined results and limitations.")]
    nb = nbf.v4.new_notebook(cells=cells, metadata={"kernelspec":{"display_name":"Python 3 (AI-ML-Internship)","language":"python","name":"python3"},"language_info":{"name":"python","version":"3.13"}})
    nbf.write(nb, OUT / "student_performance_eda.ipynb")

def build_iris():
    cells = [
        md("# Iris Dataset: Complete Exploratory Data Analysis\n\n## Objective\nInspect the genuine UCI Iris data, compare four flower measurements across the three species, assess data quality, and visualize distributions and relationships.\n\n**Source:** [UCI Iris (dataset 53)](https://archive.ics.uci.edu/dataset/53/iris), originally collected by R. A. Fisher. Measurements are centimeters."),
        md("## Load and inspect\nThe reusable UCI CSV copy lives at `data/iris.csv`. The notebook resolves paths relative to the project, independent from the student notebook."),
        code("from pathlib import Path\nimport sys\nfrom IPython.display import display, Image\nROOT = next((p for p in [Path.cwd(), *Path.cwd().parents] if (p / 'src').is_dir()), None)\nif ROOT is None: raise FileNotFoundError('Run this notebook from within the project directory.')\nsys.path.insert(0, str(ROOT / 'src'))\nimport pandas as pd\nfrom iris_analysis import FEATURES, run_iris_analysis\nraw = pd.read_csv(ROOT / 'data' / 'iris.csv')\nprint('Shape:', raw.shape, '\\nColumns:', raw.columns.tolist())\nprint('Data types:'); display(raw.dtypes.to_frame('dtype'))\ndisplay(raw.head(10))\ndisplay(raw.describe(include='all').T)"),
        md("## Data quality and cleaning\nCheck missing cells and exact duplicates. The shared cleaning function removes exact duplicate rows and imputes missing values by type if any are present. It records the actual row and cell counts."),
        code("print('Missing by column:'); display(raw.isna().sum().to_frame('missing'))\nprint('Duplicate rows:', int(raw.duplicated().sum()))\nresults = run_iris_analysis()\ncleaned = pd.read_csv(ROOT / 'data' / 'iris_cleaned.csv')\nprint('Cleaning summary:', results['cleaning'])\nprint('Species counts:', cleaned['species'].value_counts().to_dict())"),
        md("## Descriptive statistics and species comparison\nMeasurements are summarized overall and by species. These are descriptive differences in this dataset, not evidence for causal biological mechanisms."),
        code("display(cleaned[FEATURES].describe().T)\ndisplay(cleaned.groupby('species')[FEATURES].mean().round(2))"),
        md("## Visual analysis\nThe four required chart types are regenerated and saved as PNG files in `images/`. The scatter colors distinguish species."),
        code("for filename in ['iris_histograms.png','iris_scatter.png','iris_boxplot.png','iris_heatmap.png']:\n    print(filename)\n    display(Image(filename=str(ROOT / 'images' / filename)))"),
        md("## Observations, limitations, and conclusion\nThe original table has **150 rows**, no missing cells, and **3 exact duplicate rows**; the cleaned table has **147 rows** (48 setosa, 50 versicolor, 49 virginica). Mean petal length rises from **1.46 cm** for setosa to **4.26 cm** for versicolor and **5.56 cm** for virginica; mean petal width rises from **0.25 cm** to **1.33 cm** and **2.03 cm**. The petal scatter separates setosa clearly, while versicolor and virginica have some overlap. These describe this small, classic dataset and should not be generalized to all Iris populations. Correlation does not imply causation.")]
    nb = nbf.v4.new_notebook(cells=cells, metadata={"kernelspec":{"display_name":"Python 3 (AI-ML-Internship)","language":"python","name":"python3"},"language_info":{"name":"python","version":"3.13"}})
    nbf.write(nb, OUT / "iris_eda.ipynb")

if __name__ == '__main__':
    OUT.mkdir(parents=True, exist_ok=True)
    build_student(); build_iris()
